scripts.script:
if (args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "blind", duration: { rounds: 1 } });
    ui.notifications.info(`${args.target.name} 被强光致盲！`);
}

const jinwu = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "jinwu");
const stacks = jinwu ? (jinwu.getFlag("xjzl-system", "stacks") || 0) : 0;
const lvl = Math.max(1, args.move.computedLevel || 1);
const dmgPerStack = 10 + (lvl - 1) * 10;
const totalAdd = stacks * dmgPerStack;
args.output.damage += totalAdd;
if (totalAdd > 0) args.output.bonusDesc.push(`金乌爆发 (${stacks}层): +${totalAdd} 火焰伤害`);

const lvl = Math.max(1, args.move.computedLevel || 1);
const dotDmg = 10 + (lvl - 1) * 10;
const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #e67e22; background: rgba(230,126,34,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#d35400;"><i class="fas fa-sun"></i> 灼日领域 生成</div><div style="font-size:0.9em; color:#555; margin-top:3px;">区域内敌人在回合初，受到 <b style="color:#c0392b;">${dotDmg}</b> 点火焰伤害。<br>若处于无架招状态，持续陷入“目盲”。<br><span style="color:#888;">(以自身为中心 10m 移动，需玩家手动结算伤害与状态)</span></div></div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

if (!args.attacker || args.attacker.uuid === actor.uuid) return;
const stacks = thisEffect.stacks || 1;
const dmg = stacks * 5;

if (args.attacker.isReceivingReflection) return;
args.attacker.isReceivingReflection = true;
try {
    await args.attacker.applyDamage({
        amount: dmg,
        type: "fire",
        attacker: actor,
        isHit: true,
        ignoreDefense: true
    });

    const content = `<div class="xjzl-chat-card item-card" style="margin-left: 6px;">
        <header class="card-header" style="border-left: 4px solid #e74c3c;">
            <img src="${thisEffect.icon}" style="border:none;" />
            <h3 style="color: #e74c3c;">${thisEffect.name}</h3>
        </header>
        <div class="card-content-wrapper">
            <div style="font-weight:bold; color:#c0392b; margin-bottom:5px;"><i class="fas fa-fire"></i> 金乌反噬触发！</div>
            <div style="font-size:0.9em;">反噬目标: <b>${args.attacker.name}</b></div>
            <div style="margin-top:5px; border-top:1px dashed #ccc; padding-top:5px;">
                已反弹 <span style="color:red; font-weight:bold;">${dmg}</span> 点火焰伤害。
            </div>
        </div>
    </div>`;

    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({ actor: actor }),
        content: content
    });
} finally {
    args.attacker.isReceivingReflection = false;
}

if (!Macros.checkStance(actor, args)) return;
const eff = thisItem.effects.getName("棍势").toObject();
await game.xjzl.api.effects.addEffect(actor, eff);

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === "root");
    if(eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, data);
        ui.notifications.info(`${args.target.name} 被禁足！`);
    }
}

if (args.isHit) {
    const eff = thisItem.effects.getName("棍势").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
    await game.xjzl.api.effects.addEffect(actor, eff);
    ui.notifications.info("龙虎相会：获得 2 层棍势");
}

const eff = thisItem.effects.getName("鸳鸯").toObject();
eff.duration = { rounds: 3 };
await game.xjzl.api.effects.addEffect(args.target, eff);
await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info("双方已添加 [鸳鸯] 状态");

if (!Macros.checkStance(actor, args)) return;
const hasRen = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "renzhe");
const subText = hasRen ? "<span style='color:#c0392b; font-weight:bold;'><br>可消耗一层[仁者]，不消耗动作施展。</span>" : "";
const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #2980b9; background: rgba(41,128,185,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#1a5276;"><i class="fas fa-shield-alt"></i> 英雄风流触发</div><div style="font-size:0.9em; color:#555; margin-top:3px;">格挡成功！你可消耗反应动作施展【喜结连理】。${subText}</div></div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

const renzhe = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "renzhe");
if (renzhe) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "消耗仁者" },
        content: "<p>是否消耗一层 [仁者]，将敌人拉扯至身边，若无架招则禁足一回合？</p>",
        yes: { label: "消耗" }, no: { label: "保留" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "renzhe", 1);
        args.flags.wuxue_yuanyang_xijie = true;
        ui.notifications.info("已消耗仁者！");
    }
}

if (args.flags.wuxue_yuanyang_xijie && args.isHit) {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #c0392b; background: rgba(192,57,43,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#922b21;"><i class="fas fa-people-arrows"></i> 喜结连理</div><div style="font-size:0.9em; color:#555; margin-top:3px;">将 ${args.target.name} 拉扯至身边未占据的空格！</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    if (!args.target.system.martial.stanceActive) {
        await game.xjzl.api.effects.addEffect(args.target, { id: "root", duration: { rounds: 1 } });
    }
}

const renzhe = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "renzhe");
if (renzhe) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "消耗仁者" },
        content: "<p>是否消耗一层 [仁者]，虚招值+3，并变为直线范围攻击？</p>",
        yes: { label: "消耗" }, no: { label: "保留" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "renzhe", 1);
        args.flags.bonusFeint += 3;
        ui.notifications.info("虚招值+3，请手动选择直线所有敌方。");
    }
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "cuoluan", duration: { rounds: 3 } });
    ui.notifications.info(`${args.target.name} 陷入错乱！`);
}

const renzhe = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "renzhe");
if (renzhe) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "消耗仁者" },
        content: "<p>是否消耗一层 [仁者]，招式降为蓄力动作并伤害+20？</p>",
        yes: { label: "消耗" }, no: { label: "保留" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "renzhe", 1);
        args.flags.damageResult.damage += 20;
        args.flags.damageResult.breakdown += "\n+ 消耗仁者: 20";
        ui.notifications.info("招式伤害+20，降为蓄力动作。");
    }
}

const eff = thisItem.effects.getName("仁者").toObject();
const lvl = Math.max(1, args.move.computedLevel || 1);
const amount = 1 + (lvl - 1);
for(let i=0; i<amount; i++) {
    await game.xjzl.api.effects.addEffect(actor, eff);
}
ui.notifications.info(`获得 ${amount} 层 [仁者]`);

if (args.isBroken) {
    const eff = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "cuogu"));
    if(eff) {
        eff.duration = { rounds: 99 };
        await game.xjzl.api.effects.addEffect(args.target, eff);
        actor.showFloatyText("击破错骨！", { fill: "#8b0000" });
    }
}

if (args.isHit) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    if (prone) {
        await game.xjzl.api.effects.addEffect(args.target, prone);
    }
    const content = `<div class="xjzl-chat-card">
        <div style="padding:5px; padding-left:8px; border-left:4px solid #673ab7; background:rgba(103,58,183,0.1); margin-left:2px;">
            <div style="font-weight:bold; color:#512da8; font-size:1.1em;"><i class="fas fa-hand-rock"></i> 阴气牵引</div>
            <div style="font-size:0.9em; margin-top:5px; color:#555;">
                将目标 <b>${args.target.name}</b> 朝自己方向拉扯 <span style="font-weight:bold; color:#311b92;">3</span> 米！
            </div>
        </div>
    </div>`;
    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: content
    });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fengzhao"));
    if(eff) {
        eff.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, eff);
        actor.showFloatyText("穿心封招！", { fill: "#8b0000" });
    }
}

const eff = thisItem.effects.getName("白骨").toObject();
eff.origin = thisItem.uuid;

const lvl = Math.max(1, move.computedLevel || 1);
const dmgBonus = 10 + (lvl - 1) * 5;
const jiaoliBonus = (lvl - 1) * 2;

// 存入 flags 供读取，绝不污染 changes
foundry.utils.setProperty(eff, "flags.xjzl-system.dmgBonus", dmgBonus);
foundry.utils.setProperty(eff, "flags.xjzl-system.jiaoliBonus", jiaoliBonus);

eff.description += ` <br>(当前加成：伤害 +${dmgBonus}，角力检定 +${jiaoliBonus})`;

await game.xjzl.api.effects.addEffect(actor, eff);

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "弱点洞察 - 剖心刻骨" },
    content: `<p>目标 <b>${args.target.name}</b> 是否已经存在残疾（或不可磨灭的伤痕）？</p>`,
    yes: { label: "是 (伤害+30)", icon: "fas fa-check" },
    no: { label: "否", icon: "fas fa-times" }
});
if (confirm) {
    args.config.amount += 30;
    // 用 attacker 对象临时做个标记，留给 hit_once 使用
    args.attacker.pouxin_baigu = true;
}

if (args.isHit) {
    const hasCuogu = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "cuogu");
    if (hasCuogu) {
        ChatMessage.create({
            content: `<div class="xjzl-chat-card">
                <div style="padding:5px; border-left:4px solid #8b0000; background:rgba(139,0,0,0.1);">
                    <div style="font-weight:bold; color:#8b0000;"><i class="fas fa-bone-break"></i> 骨骼碎裂！</div>
                    <div style="font-size:0.9em; margin-top:3px;">目标 <b>${args.target.name}</b> 处于[错骨]，必须进行一次 <b>伤残检定 (劣势)</b>。</div>
                </div>
            </div>`,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.attacker.pouxin_baigu) {
    const hasBaigu = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "baigu");
    if (hasBaigu) {
        args.preventBaiguConsume = true;
    } else {
        const eff = thisItem.effects.getName("白骨").toObject();
        eff.origin = thisItem.uuid;
        const yinsi = thisItem.system.moves.find(m => m.name === "阴丝灌手");
        const lvl = yinsi ? Math.max(1, yinsi.computedLevel || 1) : 1;
        const dmgBonus = 10 + (lvl - 1) * 5;
        const jiaoliBonus = (lvl - 1) * 2;

        foundry.utils.setProperty(eff, "flags.xjzl-system.dmgBonus", dmgBonus);
        foundry.utils.setProperty(eff, "flags.xjzl-system.jiaoliBonus", jiaoliBonus);

        if (jiaoliBonus > 0) {
            eff.changes.push({ key: "system.skills.jiaoli.mod", mode: 2, value: String(jiaoliBonus) });
        }
        eff.description += ` <br>(当前加成：伤害 +${dmgBonus}，角力检定 +${jiaoliBonus})`;
        await game.xjzl.api.effects.addEffect(actor, eff);
    }
    delete args.attacker.pouxin_baigu;
}

if (args.move.weaponType === 'unarmed' && args.move.name !== '阴丝灌手') {
    const bonus = thisEffect.getFlag('xjzl-system', 'dmgBonus') || 10;
    args.output.damage += bonus;
    args.output.bonusDesc.push(`白骨加伤 +${bonus}`);
}

if (args.move.weaponType === 'unarmed' && args.move.name !== '阴丝灌手' && args.isHit) {
    const jiaoliBonus = thisEffect.getFlag('xjzl-system', 'jiaoliBonus') || 0;
    await Macros.requestContest({
        attacker: actor,
        defender: args.target,
        type: 'jiaoli',
        defType: 'jiaoli',
        label: '白骨 - 捏碎肢体',
        attBonus: jiaoliBonus, // <--- 直接应用对抗加值！
        outcome: {
            win: {
                text: '角力获胜！按顺序将其肢体捏碎：右腿 -> 左手 -> 左腿 -> 右手 -> 头骨。若捏碎头骨，目标直接死亡（无死检）！'
            },
            lose: {
                text: '目标拼死抵抗，未能捏碎其肢体。'
            }
        }
    });
}

if (args.move.weaponType === 'unarmed' && args.move.name !== '阴丝灌手') {
    // 只要有命中目标且没有被剖心刻骨截断，就移除白骨（去掉了之前冗余的聊天卡片提示）
    if (!args.preventBaiguConsume && args.hitCount > 0) {
        await game.xjzl.api.effects.removeEffect(actor, thisEffect.id, 1);
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "root", duration: { rounds: 1 } });
    ui.notifications.info(`${args.target.name} 被禁足！`);
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const rounds = 3 + (lvl - 1);
const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#732d91;"><i class="fas fa-chess-board"></i> 地宫生成 (${rounds}回合)</div><div style="font-size:0.9em; color:#555; margin-top:3px;">区域内友方速度+1；敌方处于困难地形。<br>请从武学把对应【地宫】AE 赋予队友。</div></div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

const lvl = Math.max(1, args.move.computedLevel || 1);
const rounds = 3 + (lvl - 1);
const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #3498db; background: rgba(52,152,219,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#2980b9;"><i class="fas fa-cloud-moon"></i> 天宫生成 (${rounds}回合)</div><div style="font-size:0.9em; color:#555; margin-top:3px;">区域内友方暴击骰-1；敌方闪避-5。<br>请从武学中把对应【天宫】AE 给双方。</div></div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

if (args.isHit) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "prone" });
}

if (!Macros.checkStance(actor, args)) return;
const eff = thisItem.effects.getName("剑光").toObject();
await game.xjzl.api.effects.addEffect(actor, eff);

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "阵法判定" },
    content: "<p>是否同时处于 [天宫] 和 [地宫] 区域内？</p>",
    yes: { label: "是" }, no: { label: "否" }
});
if(confirm) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const extraFeint = 1 + (lvl - 1);
    args.flags.bonusFeint += extraFeint;
    ui.notifications.info(`处于天地交汇，虚招值 +${extraFeint}`);
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "stun", duration: { rounds: 1 } });
    ui.notifications.info(`${args.target.name} 被定身！`);
}

const result = await foundry.applications.api.DialogV2.prompt({
    window: { title: "阵域判定" },
    content: `<div class="form-group"><label>当前所处区域：</label><select name="zone"><option value="none">无/其他</option><option value="tian">天宫</option><option value="di">地宫</option></select></div>`,
    ok: { callback: (ev, btn) => new FormData(btn.form).get("zone") }
});
if(result === "tian") {
    args.flags.ignoreBlock = true;
    args.flags.ignoreDefense = true;
    ui.notifications.info("处于天宫：本次攻击无视格挡和内防！");
} else if(result === "di") {
    args.flags.wuxue_jiugong_di = true;
    ui.notifications.info("处于地宫：无架招目标将眩晕！");
}

if (args.flags.wuxue_jiugong_di && args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "xuanyun", duration: { rounds: 1 } });
}

// 需要知道招式的当前等级，如果不知道，就默认最高等级或固定值。由于被动没法读 move.computedLevel，改读 Item 等级。
let lvl = 1;
const wuxue = actor.items.find(i => i.name === '九宫八卦剑' && i.type === 'wuxue');
if (wuxue) {
   const stanceMove = wuxue.system.moves.find(m => m.name === '戴九履一');
   if (stanceMove) lvl = Math.max(1, stanceMove.computedLevel || 1);
}
const resAmount = 10 + (lvl - 1) * 10;
args.output = resAmount;
actor.system.combat.resistances.waigong.mod += resAmount;
actor.system.combat.resistances.neigong.mod += resAmount;

if (!args.attacker || args.attacker.uuid === actor.uuid) return;
let lvl = 1;
const wuxue = actor.items.find(i => i.name === '九宫八卦剑' && i.type === 'wuxue');
if (wuxue) {
   const stanceMove = wuxue.system.moves.find(m => m.name === '戴九履一');
   if (stanceMove) lvl = Math.max(1, stanceMove.computedLevel || 1);
}
const dmg = 10 + (lvl - 1) * 10;
await args.attacker.applyHealing({ healer: actor,  amount: -dmg, type: 'hp', showScrolling: true });
args.attacker.showFloatyText(`地宫反噬 -${dmg}`, { fill: "#e74c3c" });

// 1. 拦截未入门
const lvl = move.computedLevel || 0;
if (lvl < 1) return;

// 2. 统计武器精通数量
let count = 0;
const ranks = S.combat.weaponRanks;
for (const key in ranks) {
    if (ranks[key].total >= 8) count++;
}

// 3. 计算加成并应用
const maxCount = 1 + (lvl - 1); // 初始上限1，每升1级+1
const finalBonus = Math.min(count, maxCount);
S.combat.kanpo += finalBonus;

// 1. 拦截非武学招式的调用
const wuxueItem = args.item;
if (!wuxueItem || wuxueItem.type !== 'wuxue') return;
const moves = wuxueItem.system.moves || [];
if (moves.length === 0) return;

// 2. 检查当前施展的这套武学是否全部达到精通 (>= 3级)
const isAllMastered = moves.every(m => (m.computedLevel || 0) >= 3);
if (!isAllMastered) return;

// 3. 放弃 origin 取巧，使用绝对可靠的 find 寻找本武学等级
const myItem = actor.items.find(i => i.name === '武道百炼' && i.type === 'wuxue');
if (!myItem) return;
const myMove = myItem.system.moves.find(m => m.name === '武道百炼');
const lvl = myMove?.computedLevel || 0;

// 4. 未入门拦截
if (lvl < 1) return;

// 5. 计算加成并应用
const bonus = 5 + (lvl - 1) * 5;
args.output.damage += bonus;
args.output.bonusDesc.push(`武艺详解 (精通套路): +${bonus}`);

if (!args.isHit) return;
const gender = args.target.system.info?.gender;
const lvl = Math.max(1, move.computedLevel || 1);
const duration = 3 + (lvl - 1);
const escapeDC = 19 + (lvl - 1) * 3;

if (gender === 'male') {
    const tl = thisItem.effects.getName('天罗').toObject();
    tl.duration = { rounds: duration };
    tl.description += `\n挣脱难度: DC ${escapeDC}`;
    await game.xjzl.api.effects.addEffect(args.target, tl);
    actor.showFloatyText(`${args.target.name} 陷入 [天罗]!`, { fill: "#8e44ad" });
} else if (gender === 'female') {
    const dw = thisItem.effects.getName('地网').toObject();
    dw.duration = { rounds: duration };
    dw.description += `\n挣脱难度: DC ${escapeDC}`;
    await game.xjzl.api.effects.addEffect(args.target, dw);
    actor.showFloatyText(`${args.target.name} 陷入 [地网]!`, { fill: "#8e44ad" });
} else {
    ui.notifications.warn(`${args.target.name} 性别未知，无法判断金暗双网。`);
}
